/* @autogenerated */
package net.civeira.phylax.feature.observe.metric;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Derives the RED metrics (rate, errors, duration) of the SERVER and CONSUMER spans, before the
 * sampling, so the counts are exact whatever the trace-sample-rate. Kept per minute in memory;
 * {@link #drain} hands the closed minutes (and the closed hours, for the rollup) to the store. Only
 * in memory and without locks per event other than the one of its series: it runs in the exporter
 * threads.
 */
public class MetricDeriver {

  public static final long MINUTE = 60_000;
  public static final long HOUR = 3_600_000;
  public static final String OVERFLOW = "__overflow__";
  /** Method of the checks of the probes (not requests of the application). */
  public static final String PROBE = "PROBE";
  /** Method of the calls between sources and to dependencies (edges of the service map). */
  public static final String CLIENT = "CLIENT";

  /**
   * The points of probes and edges are not requests of the source: the RED views leave them out.
   */
  /** Method of the Web Vitals of the fronts (route "<vital> <page>"). */
  public static final String VITAL = "VITAL";
  /**
   * Method of the occurrences of the issues (route: the fingerprint), so they outlive their logs.
   */
  public static final String ISSUE = "ISSUE";

  public static boolean special(final String method) {
    return PROBE.equals(method) || CLIENT.equals(method) || VITAL.equals(method)
        || ISSUE.equals(method);
  }

  /** Own traffic of the viewer and the ingestion: it is not the application. */
  private static final List<String> OWN_ROUTES =
      List.of("/observe", "/v1/traces", "/v1/logs", "/v1/metrics");

  /** Aggregate of a series in an interval. */
  static final class Agg {
    final String src;
    final String route;
    final String method;
    long count;
    long errors;
    double sumMs;
    final Histogram histogram = new Histogram();

    Agg(final String src, final String route, final String method) {
      this.src = src;
      this.route = route;
      this.method = method;
    }

    synchronized void add(final double millis, final boolean error) {
      count++;
      if (error) {
        errors++;
      }
      sumMs += millis;
      histogram.add(millis);
    }

    synchronized void add(final MetricPoint point) {
      count += point.count();
      errors += point.errors();
      sumMs += point.sumMs();
      histogram.merge(point.buckets());
    }

    synchronized MetricPoint point(final long ts, final long step) {
      return new MetricPoint(ts, step, src, route, method, count, errors, sumMs,
          histogram.counts());
    }
  }

  private final int maxSeries;
  /** minute → series key → aggregate. */
  private final Map<Long, Map<String, Agg>> minutes = new ConcurrentHashMap<>();
  /** hour → series key → aggregate of the drained minutes. */
  private final Map<Long, Map<String, Agg>> hours = new ConcurrentHashMap<>();
  private final Map<String, Set<String>> seriesBySource = new ConcurrentHashMap<>();

  public MetricDeriver(final int maxSeries) {
    this.maxSeries = maxSeries <= 0 ? 2000 : maxSeries;
  }

  /**
   * Counts a server span.
   *
   * @param route {@code http.route} (never the raw path, it would explode the cardinality)
   */
  public void record(final String src, final String route, final String method,
      final long startMillis, final double durationMillis, final boolean error) {
    if (null == src || isOwn(route)) {
      return;
    }
    String safeRoute = null == route || route.isBlank() ? "unknown" : route;
    String safeMethod = null == method ? "" : method;
    String key = src + "\n" + safeMethod + "\n" + safeRoute;
    Set<String> series = seriesBySource.computeIfAbsent(src, s -> ConcurrentHashMap.newKeySet());
    if (!series.contains(key) && series.size() >= maxSeries) {
      safeRoute = OVERFLOW;
      safeMethod = "";
      key = src + "\n\n" + OVERFLOW;
    }
    series.add(key);
    final String route0 = safeRoute;
    final String method0 = safeMethod;
    minutes.computeIfAbsent(startMillis / MINUTE * MINUTE, m -> new ConcurrentHashMap<>())
        .computeIfAbsent(key, k -> new Agg(src, route0, method0)).add(durationMillis, error);
  }

  /**
   * Counts an occurrence of an issue (route: its fingerprint). Out of max-series: there is a point
   * only for the minutes and hours in which the issue happens.
   */
  public void recordIssue(final String src, final String fingerprint, final long ts) {
    if (null == src || null == fingerprint || fingerprint.isBlank()) {
      return;
    }
    String key = src + "\n" + ISSUE + "\n" + fingerprint;
    minutes.computeIfAbsent(ts / MINUTE * MINUTE, m -> new ConcurrentHashMap<>())
        .computeIfAbsent(key, k -> new Agg(src, fingerprint, ISSUE)).add(0, false);
  }

  /**
   * Adds the minute points already stored of an hour not closed yet (before a restart), so its
   * rollup is complete when it closes.
   */
  public void seed(final List<MetricPoint> stored) {
    for (MetricPoint point : stored) {
      hours.computeIfAbsent(point.ts() / HOUR * HOUR, h -> new ConcurrentHashMap<>())
          .computeIfAbsent(key(point), k -> new Agg(point.src(), point.route(), point.method()))
          .add(point);
    }
  }

  /**
   * Every minute held in memory, open ones too (on shutdown). The points are additive: the rest of
   * an open minute, after the restart, is another point of the same minute.
   */
  public List<MetricPoint> drainAll() {
    List<MetricPoint> result = new ArrayList<>();
    for (Long minute : new ArrayList<>(minutes.keySet())) {
      Map<String, Agg> series = minutes.remove(minute);
      if (null != series) {
        series.values().forEach(agg -> result.add(agg.point(minute, MINUTE)));
      }
    }
    return result;
  }

  /** The hour points of a list of minute points: one per series and hour. */
  public static List<MetricPoint> rollup(final List<MetricPoint> minutePoints) {
    Map<Long, Map<String, Agg>> byHour = new java.util.TreeMap<>();
    for (MetricPoint point : minutePoints) {
      byHour.computeIfAbsent(point.ts() / HOUR * HOUR, h -> new java.util.LinkedHashMap<>())
          .computeIfAbsent(key(point), k -> new Agg(point.src(), point.route(), point.method()))
          .add(point);
    }
    List<MetricPoint> result = new ArrayList<>();
    byHour.forEach(
        (hour, series) -> series.values().forEach(agg -> result.add(agg.point(hour, HOUR))));
    return result;
  }

  private static String key(final MetricPoint point) {
    return point.src() + "\n" + (null == point.method() ? "" : point.method()) + "\n"
        + point.route();
  }

  /** The closed intervals, ready to store: minutes and complete hours. */
  public record Drained(List<MetricPoint> minutes, List<MetricPoint> hours) {}

  /**
   * Takes the minutes before the current one (a span can arrive a little late: a minute is closed
   * one minute after it ends) and adds them to their hour; the hours before the current one are
   * closed too.
   */
  public Drained drain(final long nowMillis) {
    long open = nowMillis / MINUTE * MINUTE - MINUTE;
    List<MetricPoint> closedMinutes = new ArrayList<>();
    for (Long minute : new ArrayList<>(minutes.keySet())) {
      if (minute < open) {
        Map<String, Agg> series = minutes.remove(minute);
        Map<String, Agg> hour =
            hours.computeIfAbsent(minute / HOUR * HOUR, h -> new ConcurrentHashMap<>());
        series.forEach((key, agg) -> {
          MetricPoint point = agg.point(minute, MINUTE);
          closedMinutes.add(point);
          hour.computeIfAbsent(key, k -> new Agg(agg.src, agg.route, agg.method)).add(point);
        });
      }
    }
    long openHour = open / HOUR * HOUR;
    List<MetricPoint> closedHours = new ArrayList<>();
    for (Long hour : new ArrayList<>(hours.keySet())) {
      if (hour < openHour) {
        hours.remove(hour).values().forEach(agg -> closedHours.add(agg.point(hour, HOUR)));
      }
    }
    return new Drained(closedMinutes, closedHours);
  }

  /** The minutes not drained yet (the current one and the previous), for the recent queries. */
  public List<MetricPoint> open() {
    List<MetricPoint> result = new ArrayList<>();
    minutes.forEach(
        (minute, series) -> series.values().forEach(agg -> result.add(agg.point(minute, MINUTE))));
    return result;
  }

  static boolean isOwn(final String route) {
    return null != route
        && OWN_ROUTES.stream().anyMatch(own -> route.equals(own) || route.startsWith(own + "/"));
  }
}
